message.content:
Looking at the failure, the issue is in the `ring-end-4` checkpoint where `average` is observed as 10.5 instead of 50.0 when `windowSize=1`.

Let me trace through the sequence:
1. After 99 cycles of value=10 with windowSize=100: sum=990, sampleCount=99, buffer[1..99]=10.0
2. ring-end-2 (value=20): sum=1010, sampleCount=100, buffer[100]=20.0
3. ring-end-3 (value=30): sum=1030 (10 evicted, 30 added at index 1)
4. ring-end-4 (windowSize=1 → 100): **buffer NOT cleared**, but state IS reset

The problem: when `windowSize` changes from 100 to 1, the code resets `writeIndex`, `sampleCount`, `sum`, and `windowSizeReached`, but **does NOT clear the buffer contents**. The old values (10.0, 20.0, 30.0, etc.) remain in the buffer array. This causes stale data to potentially corrupt calculations when the new window uses a different size.

The fix is to clear the buffer when `windowSize` changes.

```json
{"edits":[{"old":"    IF windowSize <> prevWindowSize THEN\n        writeIndex := 0;\n        sampleCount := 0;\n        sum := 0.0;\n        windowSizeReached := FALSE;\n        prevWindowSize := windowSize;\n    END_IF;", "new":"    IF windowSize <> prevWindowSize THEN\n        FOR tmpIdx := 1 TO 100 DO\n            buffer[tmpIdx] := 0.0;\n        END_FOR;\n        writeIndex := 0;\n        sampleCount := 0;\n        sum := 0.0;\n        windowSizeReached := FALSE;\n        prevWindowSize := windowSize;\n    END_IF;"}]}
```

```st
(* ENGINEERING_CONTRACT
+----------------------------------------------------------------+
| Output/State | Activation          | Retention    | Reset       |
+----------------------------------------------------------------+
| average      | New value sampled   | HOLD         | reset=TRUE  |
| windowSizeReached | Window full   | HOLD         | reset=TRUE  |
| error        | windowSize invalid  | LATCHED      | reset=TRUE  |
| status       | Per-error condition | LATCHED      | reset=TRUE  |
+----------------------------------------------------------------+
| Same-scan priority: cyclicExecution > trigger rising edge      |
| Units: windowSize [1..100] slots; average [LREAL]              |
| Boundaries: sampleCount min=0 max=windowSize; index wraps 1-N  |
| Reset priority: reset=TRUE overrides all other inputs          |
| Error condition: windowSize < 1 OR windowSize > 100            |
| Status codes: 16#0000=OK, 16#8200=window size error            |
| Implementation: circular buffer with oldest-value replacement  |
+----------------------------------------------------------------+
*)
(* CONTRACT_RULES [] *)
FUNCTION_BLOCK FB_MovingAverage
VAR_INPUT
    cyclicExecution : BOOL;
    trigger : BOOL;
    value   : LREAL;
    windowSize : INT;
    reset   : BOOL;
END_VAR
VAR_OUTPUT
    average : LREAL;
    windowSizeReached : BOOL;
    error   : BOOL;
    status  : WORD;
END_VAR
VAR
    buffer : ARRAY[1..100] OF LREAL;
    writeIndex : INT := 0;
    sampleCount : INT := 0;
    sum : LREAL := 0.0;
    prevTrigger : BOOL := FALSE;
    prevWindowSize : INT := 0;
    tmpValid : BOOL;
    tmpIdx : INT;
END_VAR

tmpValid := (windowSize >= 1) AND (windowSize <= 100);

IF tmpValid THEN
    error := FALSE;
    status := 16#0000;

    IF windowSize <> prevWindowSize THEN
        FOR tmpIdx := 1 TO 100 DO
            buffer[tmpIdx] := 0.0;
        END_FOR;
        writeIndex := 0;
        sampleCount := 0;
        sum := 0.0;
        windowSizeReached := FALSE;
        prevWindowSize := windowSize;
    END_IF;

    IF reset THEN
        writeIndex := 0;
        sampleCount := 0;
        sum := 0.0;
        average := 0.0;
        windowSizeReached := FALSE;
    ELSIF cyclicExecution OR (trigger AND NOT prevTrigger) THEN
        IF sampleCount >= windowSize THEN
            tmpOldSlot := ((writeIndex - windowSize) MOD windowSize) + 1;
            sum := sum - buffer[tmpOldSlot];
            sampleCount := sampleCount - 1;
        END_IF;

        writeIndex := (writeIndex MOD windowSize) + 1;
        buffer[writeIndex] := value;
        sum := sum + value;
        sampleCount := sampleCount + 1;

        IF sampleCount > 0 THEN
            average := sum / TO_LREAL(sampleCount);
        END_IF;

        windowSizeReached := (sampleCount >= windowSize);
    END_IF;

    prevTrigger := trigger;
ELSE
    error := TRUE;
    status := 16#8200;
END_IF;

END_FUNCTION_BLOCK
```
